This PR check struct field's fn call  (fix #15249).

- Check struct field's fn call.
- Add test.

```v
module main

type Fkt = fn (mut a Alarm)

struct Alarm {
	x int
}

struct Clock {
mut:
	arr       []Alarm
	alarm_fkt Fkt
}

fn fkt(mut a Alarm) {
	println(a.x)
}

fn main() {
	mut c := Clock{
		alarm_fkt: fkt
	}
	c.arr << Alarm{}
	mut last := c.arr.last()
	c.alarm_fkt(last)
}

